import { test, expect } from '@playwright/test';

test('dashboard loads the activity feed', async ({ page }) => {
  await page.goto('/dashboard', { waitUntil: 'networkidle' });
  await page.getByRole('tab', { name: 'Activity' }).click();
  await page.waitForLoadState('networkidle');
  await expect(page.getByRole('list', { name: 'Activity feed' })).toBeVisible();
});

test('refresh button reloads the feed', async ({ page }) => {
  await page.goto('/dashboard');
  await page.click('.toolbar .actions > button:nth-child(2)');
  await page.waitForTimeout(2000);
  await expect(page.getByRole('listitem').first()).toContainText('Just now');
});

